// The pass-through combiner, a built-in occupant of the `combiner` slot (render contract Part 2): the colour, unchanged;
// the brightness is not read. It is M1's combiner, for the single-colour debug stains; Replace-L and Multiply come with
// the colour maths (colour_composition §4.1). It reaches the assembler as a user's custom text would, through the one
// entry point (render contract Part 2). Under it a brightness-only stain renders flat white: the colour None gives the
// combiner white (colour_composition §4.1), and the brightness is not read.
// @name Pass-through
// @group Combiner
// @about The colour unchanged; the brightness is not read.
// @maps colour · brightness
// @glyph dropdown
fn combine(rgb: vec3<f32>, b: f32) -> vec3<f32> { return rgb; }

// The zero field, wired to a debug view's input, which it does not read.
// @name Zero field
// @group Source
// @about The zero field, wired to a debug view's input, which it does not read.
// @maps nothing
// @glyph name
fn source(ctx: Ctx) -> Field { return Field(0.0, 0.0, 0.0, 0.0); }

// Generated by `cargo xtask codegen` from the layout table (`crates/ledger/src/payload.rs`); do not edit.
// The debug view of `E_0` (render contract Part 6; debug_tooling_plan §B–E): scalar index 28, f32, scale diverging,
// range (−∞, ∞). A colour occupant, `present(unpack(ctx))` (gui_state_contract §3), it reads the field through
// `SimState.E_0`; its test, `catalogue_view_e_0` in `crates/kernel/tests/catalogue_views/generated.rs`, reads it
// through their Rust twins. Its colouring is the numeric template (`ledger::gen::numeric`; render_gui_spec §10.1,
// RQ-231): the stored sentinel's or unset value's line where the field has one, the non-finite guard (R-436), and the
// ramp, with `RANGE_AUTO` and `u_range` its uniforms.
// @name E_0
// @group Debug · payload fields
// @about The debug view of the payload field E_0: scalar index 28, f32.
// @maps E_0 [diverging, (−∞, ∞)]
// @glyph name
// @uniform RANGE_AUTO: u32 = 1 [0, 1]
// @uniform u_range: vec2<f32> = (0.0, 1.0)
// @control RANGE_AUTO toggle "Auto range"
// @control u_range hidden "Measured range"
fn colour(ctx: Ctx) -> vec3<f32> {
    let raw = ctx.sample.E_0;
    if ((bitcast<u32>(raw) & 0x7f800000u) == 0x7f800000u) { return debug_invalid(ctx.frag_xy); }
    let m = max(abs(uniforms.u_range.x), abs(uniforms.u_range.y));
    return ramp_coolwarm(range_norm(raw, -m, m, uniforms.RANGE_AUTO != 0u, vec2<f32>(-m, m)));
}
